//! Parser-free ordinary Sem/base-vars client; source/model work remains backend-owned.
use super::{NativeReportWork,capture_command_with_input,policy_stdout_work_using,bounded,MAX_STDERR,OUTER_WATCHDOG};
use crate::native_sem_utility_wire::{Binding,Question,Terminal};
use std::{io::{self,Write},path::PathBuf,process::Command};
fn invalid(message:&'static str)->io::Error{io::Error::new(io::ErrorKind::InvalidInput,message)}
struct Invocation{program:PathBuf,binding:Binding}
fn invocation(args:&[String])->io::Result<Invocation>{let mut program=None;let mut ordinary=vec!["analyze".to_owned()];let mut at=0;while let Some(arg)=args.get(at){at+=1;if arg=="--native-dmbc"{let value=PathBuf::from(args.get(at).ok_or_else(||invalid("native Sem executable is missing"))?);at+=1;if !value.is_absolute()||program.replace(value).is_some(){return Err(invalid("native utility requires one absolute executable"))}}else{ordinary.push(arg.clone())}}
 let parsed=crate::cli_arguments::parse(ordinary);let question=match parsed.cmd.as_str(){"sem"=>match parsed.flags.first().map(String::as_str){Some("reads")=>match(parsed.flags.get(1),parsed.flags.get(2)){(Some(owner),Some(procedure))=>Question::Reads{owner:owner.clone(),procedure:procedure.clone()},_=>Question::ReadsUsage},Some("closure")=>Question::Closure{write:parsed.flags.iter().any(|arg|arg=="--write")},Some("clothing-dump")=>Question::ClothingDump,Some("oracle")=>return Err(io::Error::new(io::ErrorKind::Unsupported,"sem oracle remains an explicit reference-only command")),_=>Question::Help},"base-vars-dead"=>Question::BaseVarsDead{tsv:parsed.flags.iter().any(|arg|arg=="--tsv"),few:parsed.flags.iter().any(|arg|arg=="--few")},_=>return Err(invalid("native Sem utility received another ordinary command"))};let root=std::fs::canonicalize(crate::cli_arguments::find_root(parsed.root))?;let binding=Binding{root,question};binding.validate()?;Ok(Invocation{program:program.ok_or_else(||invalid("native utility requires --native-dmbc"))?,binding})}
pub(super) fn run(args:&[String],stdout:&mut impl Write,stderr:&mut impl Write)->io::Result<u8>{let request=invocation(args)?;let work=NativeReportWork::new();let input=super::utility_streams::input(&request.binding,&work)?;let mut command=Command::new(&request.program);command.arg("analyze-sem-utility").arg("--root").arg(&request.binding.root).arg("--binding-stdin");let output_work=work.clone();let(status,out,operational,input_error)=capture_command_with_input(command,input,OUTER_WATCHDOG,move|stream|policy_stdout_work_using(stream,output_work),|stream|bounded(stream,MAX_STDERR))?;
 if let Some(first)=input_error{stderr.write_all(&operational)?;return Err(first)}
 let Some(code @ 0..=3)=status.code()else{stderr.write_all(&operational)?;if request.binding.question.may_write(){writeln!(stderr,"native utility commit status unknown; source may have changed; child did not return a completed utility terminal")?;}return Ok(if status.code()==Some(75){75}else{2})};
 let admitted=super::utility_streams::admit::<Terminal>(&out.bytes,&operational,&work,&|terminal|{terminal.require(&request.binding)?;if i32::from(terminal.exit)!=code{return Err(invalid("native utility terminal exit differs from child status"))}Ok(())},|terminal|(terminal.stderr,terminal.stdout));
 match admitted{Ok(admitted)=>Ok(admitted.publish(stdout,stderr)?.exit),Err(first)=>{if request.binding.question.may_write(){writeln!(stderr,"native utility commit status unknown; source may have changed; completed terminal was not admitted")?;}Err(first)}}
}
pub fn cli(args:&[String])->std::process::ExitCode{match run(args,&mut io::stdout().lock(),&mut io::stderr().lock()){Ok(code)=>std::process::ExitCode::from(code),Err(error)=>{eprintln!("analyze: {error}");std::process::ExitCode::from(2)}}}
